/* ============================================================
   FREAKYVERSE — TEASER DE LA FAILLE SCELLÉE
   Chargé uniquement quand on clique sur la faille mystère.
   Les sons et la police pixel sont intégrés dans ce fichier.
   ------------------------------------------------------------
   Pour rejouer la séquence "première fois" pendant vos tests,
   tapez dans la console du navigateur :
     localStorage.removeItem('fv_teaser'); location.reload();
   ============================================================ */
(function(){
'use strict';
const ASSETS={"pas": {"m": "audio/mpeg", "b": ""}, "calme_1": {"m": "audio/wav", "b": ""}, "calme_2": {"m": "audio/wav", "b": ""}, "chuchote_1": {"m": "audio/wav", "b": ""}, "rire_1": {"m": "audio/wav", "b": ""}, "cri_1": {"m": "audio/wav", "b": ""}, "vt323": {"m": "font/woff2", "b": ""}};
const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
let muted=false; try{ muted=localStorage.getItem('fv_sound')==='0'; }catch(e){}
let ctx=null, master=null; const buf={};
let root=null, els={}, running=false, skipped=false, quick=false, typing=false, screamed=false;
let clickWake=null, glitchTimer=null, footsteps=null;
const waiters=new Set(), ABORT={};
const rnd=Math.random, clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const b2buf=b=>{const s=atob(b),a=new Uint8Array(s.length);for(let i=0;i<s.length;i++)a[i]=s.charCodeAt(i);return a.buffer};

/* ---------- attentes interrompables ---------- */
const W=ms=>new Promise((res,rej)=>{
  if(skipped)return rej(ABORT);
  const t=setTimeout(()=>{waiters.delete(w);res()},ms);
  const w=()=>{clearTimeout(t);waiters.delete(w);rej(ABORT)};
  waiters.add(w);
});
const hold=ms=>new Promise((res,rej)=>{
  if(skipped)return rej(ABORT);
  const done=()=>{clearTimeout(t);clickWake=null;waiters.delete(w);res()};
  const t=setTimeout(done,ms);
  const w=()=>{clearTimeout(t);clickWake=null;waiters.delete(w);rej(ABORT)};
  waiters.add(w); clickWake=done;
});
function skip(){ skipped=true; [...waiters].forEach(f=>f()); }

/* ---------- styles du teaser ---------- */
function injectCss(){
  if(document.getElementById('possCss'))return;
  const st=document.createElement('style'); st.id='possCss';
  st.textContent=`
  #possess{position:fixed;inset:0;z-index:300;display:none;background:transparent;font-family:'FVPixel',ui-monospace,monospace;color:#d9d3ea}
  #possess.on{display:block}
  #possess.black{background:#000}
  #possess .pgrain{position:absolute;inset:0;opacity:0;pointer-events:none;background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='2'/></filter><rect width='160' height='160' filter='url(%23n)'/></svg>");animation:pgrain .5s steps(5) infinite}
  #possess.black .pgrain{opacity:.07}
  @keyframes pgrain{0%{background-position:0 0}20%{background-position:-40px 22px}40%{background-position:31px -58px}60%{background-position:-70px -10px}80%{background-position:12px 64px}100%{background-position:0 0}}
  #possess .pvig{position:absolute;inset:0;pointer-events:none;opacity:0;background:radial-gradient(ellipse at center,transparent 35%,#000 100%)}
  #possess.black .pvig{opacity:1}
  #possess .pslices{position:absolute;inset:0;overflow:hidden;pointer-events:none}
  #possess .pslices i{position:absolute;left:-5%;width:110%;mix-blend-mode:screen}
  #possess .pflash{position:absolute;inset:0;opacity:0;pointer-events:none;background:radial-gradient(circle at 50% 50%,#ff2a2a 0,#a00010 55%,#300 100%)}
  #possess .pbox{position:absolute;left:50%;bottom:9vh;transform:translateX(-50%);width:min(880px,88vw);padding:1.1rem 1.4rem 1.3rem;background:rgba(6,3,10,.86);border:1px solid rgba(255,255,255,.16);opacity:0;transition:opacity .25s}
  #possess .pbox.show{opacity:1}
  #possess .pname{font-size:clamp(.8rem,1.6vw,1.05rem);letter-spacing:.2em;margin-bottom:.5rem;opacity:.9}
  #possess .ptext{font-size:clamp(1.15rem,2.7vw,1.9rem);line-height:1.35;min-height:2.7em}
  #possess .ptext .w{display:inline-block;white-space:nowrap}
  #possess .ptext .c{display:inline-block;opacity:0}
  #possess .ptext .c.v{opacity:1}
  .p-calme .ptext{color:#d9d3ea}.p-calme .pname{color:#b9a6e0}
  .p-rire .ptext{color:#ffa6cf}.p-rire .pname{color:#ff7fb0}
  .p-rire .c.v{animation:pwave 1s ease-in-out infinite;animation-delay:calc(var(--i)*70ms)}
  @keyframes pwave{0%,100%{transform:translateY(0)}50%{transform:translateY(-.12em)}}
  .p-guette .ptext{color:#86a5e6;font-size:clamp(1rem,2.2vw,1.6rem);opacity:.9}.p-guette .pname{color:#6fa8dc}
  #possess .pscream{position:absolute;inset:0;display:none;place-items:center;text-align:center;padding:0 4vw;color:#ff1e1e;font-size:clamp(2.1rem,7.2vw,6.2rem);line-height:1.08;text-shadow:0 0 28px #f00,0 0 60px #800;pointer-events:none}
  #possess .pscream.on{display:grid;animation:pscream .09s steps(2) infinite}
  @keyframes pscream{0%{transform:translate(-6px,3px) scale(1.02)}100%{transform:translate(6px,-3px) scale(1)}}
  #possess .pskip{position:absolute;right:1.4rem;bottom:1.2rem;font:inherit;font-size:.95rem;color:#8a8294;background:none;border:1px solid rgba(255,255,255,.18);padding:.4rem .9rem;cursor:pointer;opacity:0;transition:opacity 1s}
  #possess .pskip.show{opacity:.7}
  #possess .peyes{position:absolute;inset:0;pointer-events:none;transition:transform .05s}
  #possess .pe{position:absolute;display:flex;gap:calc(15px*var(--s,1));transform:translate(-50%,-50%) scale(var(--s,1));opacity:0;filter:blur(var(--b,0px));transition:opacity .5s}
  #possess .pe.open{opacity:var(--o,1)}
  #possess .pe .e{position:relative;width:30px;height:11px;border-radius:50%/60%;background:radial-gradient(ellipse at center,#fff3c4 0,#ff7a3a 45%,#b0141a 80%);box-shadow:0 0 14px 3px rgba(255,70,40,.7),0 0 40px 8px rgba(255,30,20,.3);transform:scaleY(0);transition:transform .4s cubic-bezier(.2,1.4,.4,1),box-shadow .3s}
  #possess .pe.open .e{transform:scaleY(1)}
  #possess .pe.open.blink .e{transform:scaleY(.08);transition-duration:.07s}
  #possess .pe .e i{position:absolute;left:50%;top:50%;width:4px;height:135%;background:#150000;border-radius:50%;transform:translate(calc(-50% + var(--px,0px)),calc(-50% + var(--py,0px)))}
  #possess.flare .pe .e{box-shadow:0 0 22px 7px rgba(255,60,40,1),0 0 80px 22px rgba(255,20,10,.65)}
  #possess.stress .pgrain{opacity:.18}
  #possess.stress .pvig{animation:pvig 1.1s ease-in-out infinite}
  @keyframes pvig{0%,100%{transform:scale(1)}50%{transform:scale(1.22)}}
  #possess.stress .pbox{animation:ptrem .1s steps(2) infinite}
  @keyframes ptrem{0%{transform:translateX(-50%)}100%{transform:translate(calc(-50% + 2px),1px)}}
  #possess.jit .peyes{transform:translate(4px,-3px)}
  #possess.jit .pgrain{opacity:.35}
  main.pshake{animation:pshake .12s steps(2) infinite}
  @keyframes pshake{0%{transform:translate(-5px,2px)}100%{transform:translate(6px,-3px)}}
  `;
  document.head.appendChild(st);
}

/* ---------- construction de l'écran ---------- */
function build(){
  if(root)return;
  root=document.createElement('div'); root.id='possess';
  root.innerHTML=`<div class="pgrain"></div><div class="pvig"></div><div class="pslices"></div><div class="peyes"></div>
    <div class="pbox"><div class="pname">???</div><div class="ptext"></div></div>
    <div class="pscream"></div><div class="pflash"></div>
    <button class="pskip" type="button">Passer (Échap)</button>`;
  document.body.appendChild(root);
  els={eyes:root.querySelector('.peyes'),slices:root.querySelector('.pslices'),box:root.querySelector('.pbox'),name:root.querySelector('.pname'),
       text:root.querySelector('.ptext'),scream:root.querySelector('.pscream'),flash:root.querySelector('.pflash'),
       skip:root.querySelector('.pskip')};
  els.skip.addEventListener('click',e=>{e.stopPropagation();skip()});
  root.addEventListener('click',()=>{ if(typing)quick=true; else if(clickWake)clickWake(); });
  let mmWait=false;
  root.addEventListener('mousemove',e=>{            /* les yeux suivent le curseur */
    if(reduce||mmWait)return; mmWait=true;
    requestAnimationFrame(()=>{ mmWait=false;
      root.style.setProperty('--px',((e.clientX/innerWidth-.5)*7).toFixed(1)+'px');
      root.style.setProperty('--py',((e.clientY/innerHeight-.5)*5).toFixed(1)+'px'); });
  });
}

/* ---------- audio ---------- */
let ready=null;
function prepare(){
  if(ready)return ready;
  ready=(async()=>{
    try{ const f=new FontFace('FVPixel',b2buf(ASSETS.vt323.b)); await f.load(); document.fonts.add(f); }catch(e){}
    if(muted)return;
    const AC=window.AudioContext||window.webkitAudioContext; if(!AC)return;
    ctx=new AC(); master=ctx.createGain(); master.gain.value=.85; master.connect(ctx.destination);
    for(const k in ASSETS){
      if(!ASSETS[k].m.startsWith('audio'))continue;
      try{ buf[k]=await ctx.decodeAudioData(b2buf(ASSETS[k].b)); }catch(e){}
    }
  })();
  return ready;
}
function snd(name,rate,vol,at){
  if(!ctx||!buf[name])return null;
  const s=ctx.createBufferSource(); s.buffer=buf[name]; s.playbackRate.value=rate;
  const g=ctx.createGain(); g.gain.value=vol; s.connect(g); g.connect(master);
  s.start(at||ctx.currentTime); return {s,g};
}
function noiseBurst(at,dur,hpf,vol){
  if(!ctx)return;
  const n=Math.floor(ctx.sampleRate*dur), b=ctx.createBuffer(1,n,ctx.sampleRate), d=b.getChannelData(0);
  for(let i=0;i<n;i++) d[i]=(Math.random()*2-1)*Math.pow(1-i/n,2);
  const s=ctx.createBufferSource(); s.buffer=b;
  const f=ctx.createBiquadFilter(); f.type='highpass'; f.frequency.value=hpf;
  const g=ctx.createGain(); g.gain.value=vol;
  s.connect(f); f.connect(g); g.connect(master); s.start(at);
}
function snap(at){ noiseBurst(at,.04,1800,.55); if(!ctx)return;
  const o=ctx.createOscillator(), g=ctx.createGain();
  o.frequency.setValueAtTime(900,at); o.frequency.exponentialRampToValueAtTime(120,at+.05);
  g.gain.setValueAtTime(.25,at); g.gain.exponentialRampToValueAtTime(.0001,at+.07);
  o.connect(g); g.connect(master); o.start(at); o.stop(at+.08); }
function rumble(){ if(!ctx)return; const t=ctx.currentTime, o=ctx.createOscillator(), g=ctx.createGain();
  o.type='sine'; o.frequency.setValueAtTime(60,t); o.frequency.exponentialRampToValueAtTime(34,t+.9);
  g.gain.setValueAtTime(.0001,t); g.gain.linearRampToValueAtTime(.3,t+.08); g.gain.exponentialRampToValueAtTime(.0001,t+1);
  o.connect(g); g.connect(master); o.start(t); o.stop(t+1.05); }

/* ---------- les répliques ---------- */
const EX={
  calme: {voice:['calme_1','calme_2'],pitch:1.00,cps:22,cls:'p-calme', vol:.55},
  guette:{voice:['chuchote_1'],       pitch:.95, cps:16,cls:'p-guette',vol:.45},
  rire:  {voice:['rire_1'],           pitch:1.05,cps:30,cls:'p-rire',  vol:.6}
};
function blip(e){ if(!ctx)return; snd(e.voice[rnd()*e.voice.length|0], clamp(e.pitch+(rnd()*2-1)*.1,.6,1.5), e.vol); }
async function say(text,key,opt={}){
  const e=EX[key];
  els.box.className='pbox show '+e.cls; els.name.textContent='???';
  els.text.innerHTML=''; const chars=[]; let i=0;
  text.split(' ').forEach((word,wi,arr)=>{
    const w=document.createElement('span'); w.className='w';
    for(const ch of word){ const c=document.createElement('span'); c.className='c'; c.textContent=ch; c.style.setProperty('--i',i++); w.appendChild(c); chars.push(c); }
    els.text.appendChild(w); if(wi<arr.length-1)els.text.appendChild(document.createTextNode(' '));
  });
  quick=false; typing=true;
  for(const c of chars){
    c.classList.add('v'); const ch=c.textContent;
    if(/[\p{L}\p{N}]/u.test(ch)) blip(e);
    if(quick)continue;
    let d=1000/e.cps; if('.!?…'.includes(ch))d+=260; else if(',:;'.includes(ch))d+=130;
    await W(d);
  }
  typing=false; quick=false;
  await hold(opt.hold??1500);
  els.box.classList.remove('show'); await W(280);
}

/* ---------- effets visuels ---------- */
function glitchStart(){
  if(reduce)return;
  document.querySelector('main')?.classList.add('pshake');
  const draw=()=>{
    els.slices.innerHTML='';
    for(let k=0;k<7;k++){
      const b=document.createElement('i');
      b.style.top=(rnd()*100)+'%'; b.style.height=(1+rnd()*9)+'%';
      b.style.background=rnd()<.5?'rgba(255,40,60,.4)':'rgba(40,220,255,.35)';
      b.style.transform=`translateX(${(rnd()*2-1)*50}px)`; els.slices.appendChild(b);
    }
  };
  draw(); glitchTimer=setInterval(draw,70);
}
function glitchStop(){ clearInterval(glitchTimer); glitchTimer=null; if(els.slices)els.slices.innerHTML=''; document.querySelector('main')?.classList.remove('pshake'); }
function flashOnce(){
  if(reduce)return;
  els.flash.style.transition='none'; els.flash.style.opacity=1; void els.flash.offsetWidth;
  els.flash.style.transition='opacity .5s ease-out'; els.flash.style.opacity=0;
}
/* ----- la tension : battements de cœur qui s'accélèrent, dissonance qui monte, chuchotements ----- */
let stress=null, eyeTimers=[], eyePairs=[];
function heart(at){
  [[0,.4,62],[.17,.27,55]].forEach(([d,v,f])=>{
    const o=ctx.createOscillator(), g=ctx.createGain();
    o.type='sine'; o.frequency.setValueAtTime(f*1.6,at+d); o.frequency.exponentialRampToValueAtTime(f*.6,at+d+.12);
    g.gain.setValueAtTime(v,at+d); g.gain.exponentialRampToValueAtTime(.0001,at+d+.16);
    o.connect(g); g.connect(master); o.start(at+d); o.stop(at+d+.2);
  });
}
function startStress(){
  if(stress)return;
  stress={on:true,t0:performance.now(),timers:[],nodes:[]};
  root.classList.add('stress');
  const el=()=>(performance.now()-stress.t0)/1000;
  if(ctx){
    const t=ctx.currentTime;
    [[220,1],[311.13,1],[233.08,1]].forEach(([f],k)=>{            /* notes en conflit (triton + seconde mineure) */
      const o=ctx.createOscillator(), g=ctx.createGain(), l=ctx.createOscillator(), lg=ctx.createGain();
      o.type='sine'; o.frequency.setValueAtTime(f,t); o.frequency.linearRampToValueAtTime(f*1.07,t+6);
      l.frequency.value=4.2+k*1.3; lg.gain.value=.012; l.connect(lg); lg.connect(g.gain);
      g.gain.setValueAtTime(.0001,t); g.gain.linearRampToValueAtTime(.045,t+4.5);
      o.connect(g); g.connect(master); o.start(t); l.start(t); stress.nodes.push({o,l,g});
    });
    const beat=()=>{ if(!stress||!stress.on)return; heart(ctx.currentTime);
      stress.timers.push(setTimeout(beat,60000/clamp(60+el()*17,60,150))); };
    const whisper=()=>{ if(!stress||!stress.on)return;
      if(buf.chuchote_1)snd('chuchote_1',.5+rnd()*.35,.07+Math.min(.2,el()*.04));
      stress.timers.push(setTimeout(whisper,clamp(1100-el()*130,260,1100)+rnd()*260)); };
    beat(); stress.timers.push(setTimeout(whisper,500));
  }
  if(!reduce){                                                     /* micro-secousses irrégulières */
    const jit=()=>{ if(!stress||!stress.on)return; root.classList.add('jit');
      setTimeout(()=>root.classList.remove('jit'),90);
      stress.timers.push(setTimeout(jit,600+rnd()*1100)); };
    stress.timers.push(setTimeout(jit,900));
  }
}
function stopStress(hard){
  if(!stress)return;
  const s=stress; stress=null; s.on=false; s.timers.forEach(clearTimeout);
  if(ctx){ const t=ctx.currentTime, f=hard?.05:.6;
    s.nodes.forEach(n=>{ try{ n.g.gain.cancelScheduledValues(t); n.g.gain.setValueAtTime(Math.max(.0001,n.g.gain.value),t);
      n.g.gain.exponentialRampToValueAtTime(.0001,t+f); n.o.stop(t+f+.05); n.l.stop(t+f+.05); }catch(e){} }); }
  root.classList.remove('stress','jit');
}

/* ----- les yeux dans la pénombre ----- */
function makeEyes(){
  clearEyes();
  const pts=[]; let tries=0;
  while(pts.length<15&&tries<400){
    tries++;
    const x=6+rnd()*88, y=8+rnd()*84;
    if(x>14&&x<86&&y>62)continue;                                   /* on garde la zone du texte dégagée */
    if(pts.some(p=>Math.hypot(p.x-x,(p.y-y)*.6)<13))continue;
    pts.push({x,y});
  }
  pts.forEach(p=>{
    const s=.55+rnd()*1.15, pe=document.createElement('div'); pe.className='pe';
    pe.style.left=p.x+'%'; pe.style.top=p.y+'%';
    pe.style.setProperty('--s',s.toFixed(2)); pe.style.setProperty('--b',s<.9?'1.2px':'0px'); pe.style.setProperty('--o',(.5+Math.min(.5,s*.32)).toFixed(2));
    pe.innerHTML='<span class="e"><i></i></span><span class="e"><i></i></span>';
    els.eyes.appendChild(pe); eyePairs.push(pe);
  });
}
function clearEyes(){ eyeTimers.forEach(clearTimeout); eyeTimers=[]; eyePairs=[]; if(els.eyes)els.eyes.innerHTML=''; }
async function summonEyes(){
  makeEyes();
  eyePairs.forEach((p,i)=>eyeTimers.push(setTimeout(()=>p.classList.add('open'),150+i*210+rnd()*90)));
  if(!reduce){
    const blink=()=>{ const open=eyePairs.filter(p=>p.classList.contains('open'));
      for(let k=0;k<2&&open.length;k++){ const p=open[rnd()*open.length|0]; p.classList.add('blink'); setTimeout(()=>p.classList.remove('blink'),110); }
      eyeTimers.push(setTimeout(blink,500+rnd()*800)); };
    eyeTimers.push(setTimeout(blink,1200));
  }
  await W(3700);
}
async function doScream(){
  screamed=true;
  els.box.classList.remove('show');
  stopStress(true);                                 /* le son se coupe net : silence, et les yeux nous fixent */
  await W(1000);
  els.scream.innerHTML="CE N'EST PAS ENCORE PRÊT,<br>SORS D'ICI !"; els.scream.classList.add('on');
  root.classList.add('flare'); flashOnce();
  if(!reduce)document.querySelector('main')?.classList.add('pshake');
  snd('cri_1',.85,.95); snd('cri_1',.62,.7); noiseBurst(ctx?ctx.currentTime:0,.25,600,.5);
  await W(2100);
  els.scream.classList.remove('on'); document.querySelector('main')?.classList.remove('pshake');
  root.classList.remove('flare'); clearEyes();
  await W(1500);
}

/* ---------- séquence ---------- */
function onKey(e){ if(e.key==='Escape'){ e.stopImmediatePropagation(); skip(); } }
async function run(w){
  if(running)return; running=true; skipped=false; quick=false; typing=false; screamed=false;
  let seen=false; try{ seen=localStorage.getItem('fv_teaser')==='1'; }catch(e){}
  injectCss(); build();
  document.body.style.overflow='hidden';
  root.classList.remove('black'); root.classList.add('on'); els.box.className='pbox';
  document.addEventListener('keydown',onKey,true);
  try{
    await prepare();
    if(ctx&&ctx.state==='suspended')ctx.resume();
    if(window.FVduck)window.FVduck(true);
    setTimeout(()=>els.skip.classList.add('show'),2200);

    /* 1. les coutures lâchent, l'écran se déchire */
    if(window.FVmarkTorn)window.FVmarkTorn(w);
    if(ctx){ const t=ctx.currentTime; [0,.14,.3,.46].forEach(d=>snap(t+d)); rumble(); }
    glitchStart();
    await W(seen?450:850);
    glitchStop();

    /* 2. le noir total */
    root.classList.add('black');
    await W(seen?650:950);

    /* 3. des pas qui approchent (puis plus rien) */
    if(!seen){
      if(ctx&&buf.pas){
        footsteps=snd('pas',1,.0001);
        const t=ctx.currentTime; footsteps.g.gain.setValueAtTime(.05,t); footsteps.g.gain.exponentialRampToValueAtTime(.9,t+2.4);
      }
      await W(2400);
      try{ footsteps&&footsteps.s.stop(); }catch(e){} footsteps=null;
      await W(1100);
    }

    /* 4. le dialogue */
    if(seen){
      const pool=['…Bientôt.','Chut. Ils arrivent.','Patience… ils arrivent.'];
      await say(pool[rnd()*pool.length|0],'guette',{hold:1300});
      await W(500);
    }else{
      await say('…Ils arrivent bientôt ?','guette');
      await say("Ça faisait longtemps qu'on n'avait pas eu de la compagnie.",'calme',{hold:1700});
      await say("J'ai hâte.",'rire',{hold:1300});
      await W(700);
      startStress();                                  /* ils réalisent qu'on les écoute : l'ambiance devient pesante */
      await say('…Tu nous écoutes ?','calme',{hold:500});
      await summonEyes();
      await doScream();
    }
  }catch(e){ if(e!==ABORT)console.error(e); }
  finally{ cleanup(); }
}
function cleanup(){
  glitchStop(); clearInterval(glitchTimer); stopStress(true); clearEyes();
  root.classList.remove('flare');
  try{ footsteps&&footsteps.s.stop(); }catch(e){} footsteps=null;
  document.removeEventListener('keydown',onKey,true);
  els.scream.classList.remove('on'); els.box.classList.remove('show'); els.skip.classList.remove('show');
  if(screamed){ try{localStorage.setItem('fv_teaser','1')}catch(e){} if(window.FVmarkTorn)window.FVmarkTorn(); }
  const dur=skipped?.4:1.2;
  root.style.transition=`opacity ${dur}s ease`; root.style.opacity=0;
  setTimeout(()=>{
    root.classList.remove('on','black'); root.style.transition=''; root.style.opacity='';
    document.body.style.overflow='';
    if(window.FVduck)window.FVduck(false);
    if(ctx)ctx.suspend();
    running=false;
  },dur*1000+60);
}

window.FVTeaser={run};
})();
